```python
import itertools

def n_queens(n: int) -> int:
    def is_attacking(row, col):
        for i in range(n):
            if i != row and i != col and abs(i - row) == abs(i - col):
                return False
        return True

    def backtrack(row, col):
        if row == n:
            return 1
        count = 0
        for i in range(n):
            if is_attacking(row, i) and not is_attacking(i, col):
                count += backtrack(row + 1, i)
        return count

    return backtrack(0, 0)

