from typing import List

def sliding_max(nums: List[int], k: int) -> List[int]:
    max_val = float('-inf')
    left = 0
    for right in range(len(nums)):
        if right - left + 1 == k:
            if nums[right] > max_val:
                max_val = nums[right]
        if right - left + 1 > k:
            if nums[left] > max_val:
                max_val = nums[left]
            left += 1
    return [max_val] + nums[left:right + 1]
