To evaluate an arithmetic expression using only the Python standard library, we can implement a recursive function. The function will traverse the expression and perform the corresponding arithmetic operations. Let's go ahead and implement this:

```python
import re
from operator import add, sub, mul, truediv

def evaluate(expr: str) -> int:
    # Regular expression to match operators and numbers
    expr = re.sub(r'[+—/×÷]', '', expr)
    stack = []

    def evaluate_sub(expr: str) -> int:
        nonlocal stack
        if expr[0] == '-':
            return -int(expr[1:])
        if expr[0] == '+':
            return int(expr[1:])
        if expr[0] == '/':
            return truediv(int(expr[1:]), int(expr[2:]))
        if expr[0] == '*':
            return mul(int(expr[1:]), int(expr[2:]))
        return int(expr[1:])

    def evaluate_add(expr: str) -> int:
        nonlocal stack
        if expr[0] == '+':
            return evaluate_sub(expr[1:])
        return int(expr[1:])

    def evaluate_subtract(expr: str) -> int:
        nonlocal stack
        if expr[0] == '-':
            return -int(expr[1:])
        if expr[0] == '+':
            return -int(expr[1:])
        if expr[0] == '/':
            return truediv(int(expr[1:]), int(expr[2:]))
        if expr[0] == '*':
            return mul(int(expr[1:]), int(expr[2:]))
        return int(expr[1:])

    def evaluate_div(expr: str) -> int:
        nonlocal stack
        if expr[0] == '/':
            return truediv(int(expr[1:]), int(expr[2:]))
        return int(expr[1:])

    # Traverse the expression
    for char in expr:
        if char == ' ':
            continue
        elif char == '-' or char == '+' or char == '/' or char == '*' or char == '%':
            continue
        elif char.isdigit():
            if char not in ['+', '-', '*', '/']:
                raise ValueError(f"Invalid character '{char}'")
            stack.append(int(char))
        elif char == '(':
            evaluate_add(expr)
        elif char == ')':
            evaluate_sub(expr)
        elif char == ',':
            continue
        elif char == '=':
            break

    # Evaluate the remaining expression
    return evaluate_subtract(evaluate_add(expr))

# Test the function
print(evaluate("3 + 5 * 2 - 1"))
```

