from typing import List
import sys

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.sizes = [1] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int) -> None:
        x, y = self.find(x), self.find(y)
        if x == y:
            return
        if self.sizes[x] < self.sizes[y]:
            x, y = y, x
        self.parent[y] = x
        self.sizes[x] += self.sizes[y]

def count_islands(grid: List[str]) -> int:
    grid = [list(row) for row in grid]
    n = len(grid)
    uf = UnionFind(n)

    def get_islands(x: int, y: int) -> List[int]:
        if grid[x][y] == '0':
            return []
        land_islands = []
        if x > 0:
            if get_islands(x-1, y) != []:
                land_islands.append((x-1, y))
        if y > 0:
            if get_islands(x, y-1) != []:
                land_islands.append((x, y-1))
        if x < n-1:
            if get_islands(x+1, y) != []:
                land_islands.append((x+1, y))
        if y < n-1:
            if get_islands(x, y+1) != []:
                land_islands.append((x, y+1))
        return land_islands

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '1':
                union(i, j, uf)

    return len(union(0, 0, uf)) - 1

def union(i: int, j: int, uf: UnionFind) -> None:
    x1, y1 = uf.find(i), uf.find(j)
    if x1 == y1:
        return
    uf.union(x1, y1)
    uf.sizes[x1] += uf.sizes[y1]

# Example usage
grid = [["1","1","1","1","0"],
["1","1","0","1","0"],
["1","1","1","1","4"],
["1","1","1","1","3"],
["0","0","0","1","0"]]
print(count_islands(grid))  # Output: 12
```

This solution works by first finding all islands (cells containing land) and then using the Union-Find data structure to union them. The `count_islands` function then counts the number of islands by checking the sizes of connected components.

